"""Check a JSON value against a JSON Schema, and fail when it does not match.

The schema's dialect follows its `$schema` keyword and defaults to Draft
2020-12, as everywhere else in Azathoth. A schema refers only to itself: no
`$ref` is fetched from the network. A value that matches is returned
unchanged, so the steps after this one read the checked value.

A value that does not match fails the step with its first violation, by JSON
path and then by message, and the number of others. Long messages are cut
short, because the engine quotes only the end of a tool's error output.
"""

import json
import sys

TOOL = "validate_json"
INPUTS = ("value", "schema")
MESSAGE_LIMIT = 300
PATH_LIMIT = 120


def fail(status, message):
    sys.stderr.buffer.write(message.encode("utf-8"))
    sys.exit(status)


def read_inputs():
    inputs = json.loads(sys.stdin.buffer.read().decode("utf-8"))

    for name in inputs:
        if name not in INPUTS:
            fail(2, f"{TOOL} does not take the input {name!r}.")

    for name in INPUTS:
        if name not in inputs:
            fail(2, f"{TOOL} needs the input {name!r}.")

    return inputs


def shorten(text, limit):
    if len(text) <= limit:
        return text

    return text[: limit - 1] + "…"


def sentence(text):
    return text if text.endswith("…") else f"{text}."


def render_path(parts):
    return "$" + "".join(f"[{part}]" if isinstance(part, int) else f".{part}" for part in parts)


inputs = read_inputs()
schema = inputs["schema"]

if not isinstance(schema, (dict, bool)):
    fail(2, f"{TOOL} needs 'schema' to be a JSON Schema: an object or a boolean.")

try:
    from jsonschema import Draft202012Validator
    from jsonschema.exceptions import SchemaError
    from jsonschema.validators import validator_for
    from referencing.exceptions import Unresolvable
except ImportError:
    fail(
        2,
        f"{TOOL} needs the jsonschema package, which Azathoth installs; "
        "run it with the Python that runs Azathoth.",
    )

if isinstance(schema, bool):
    validator_class = Draft202012Validator
else:
    validator_class = validator_for(schema, default=Draft202012Validator)

    try:
        validator_class.check_schema(schema)
    except SchemaError as error:
        problem = shorten(error.message, MESSAGE_LIMIT)
        fail(2, sentence(f"{TOOL} was given an invalid schema: {problem}"))

try:
    violations = sorted(
        (render_path(error.absolute_path), error.message)
        for error in validator_class(schema).iter_errors(inputs["value"])
    )
except Unresolvable as error:
    reference = shorten(str(error), MESSAGE_LIMIT)
    fail(2, sentence(f"{TOOL} could not resolve a reference in the schema: {reference}"))

if violations:
    path, message = violations[0]
    others = len(violations) - 1
    rest = ""

    if others == 1:
        rest = " (and 1 more error)"
    elif others > 1:
        rest = f" (and {others} more errors)"

    location = shorten(path, PATH_LIMIT)
    detail = shorten(message, MESSAGE_LIMIT)
    fail(1, sentence(f"{TOOL} rejected the value at {location}: {detail}{rest}"))

sys.stdout.buffer.write(json.dumps({"value": inputs["value"]}, ensure_ascii=False).encode("utf-8"))
